mapper.select:
   select distinct a.cash_id anapleroticId,
    	  b.EFF_DATE effDate
     from FIN_CASH_INFO a
    inner join FIN_CLAWBACK_CALC_RULE b
       on a.cash_id = b.cash_id
	where Is_Calc = #{isCalcY}
	  and Finprod_Type = #{finprodType}
	  and CASH_TYPE_1 = #{cashType1}
	  and CASH_TYPE_2 = #{cashType2} 
	  and FINPROD_ID = #{finprodId}

select a.CAWLBACK_RULE anapleroticRule,/*回补方式*/ a.CAWLBACK_TYPE anapleroticType, /*回补形式*/ a.Basis anapleroticBasic, h.ast_vdate_type astVluDateType,/*资产净值日*/ a.Eff_Date effDate, a.cash_id anapleroticId, h.remark remark, nvl(j.FINPROD_ID,b.FINPROD_ID) finprodId, i.PROD_STYLE prodStyle, nvl(j.FINPROD_ABBR,g.FINPROD_ABBR) finprodAbbr, i.FINPROD_ID sFinprodId, c.ACCR_CYCLE_UNIT anapleroticFrequency, /*回补规则*/ c.ACCR_TDAY_RULE cycleTdayRule,/*营业日准则*/ c.F_ACCR_DATE firstAnapleroticDate, c.F_ACCR_END_DATE firstAnapleroticCycleEndDate, f.COEFFICIENT*100 anapleroticRatio from FIN_CLAWBACK_CALC_RULE a inner join FIN_CASH_INFO b on b.cash_id= a.cash_id left join Fin_Float_Counting_Rule c on a.cash_id = c.cash_id and a.Eff_Date = c.EFF_DATE left join fin_product_add e on b.FINPROD_ID = e.FINPROD_ID left join Fin_Float_Calc_Rule_Detail f on a.cash_id = f.cash_id and a.Eff_Date = f.EFF_DATE left join fin_product g on b.FINPROD_ID = g.FINPROD_ID left join FIN_FLOAT_CALC_RULE h on a.cash_id = h.cash_id and a.Eff_Date = h.EFF_DATE LEFT join PRD_LAYER_PARAM i on i.FINPROD_ID = b.FINPROD_ID left join FIN_PRODUCT j on j.FINPROD_ID = g.P_FINPROD_ID where b.Finprod_Type = #{finprodType} and b.Is_Calc = #{isCalcY} and b.CASH_TYPE_1 = #{cashType1} and b.CASH_TYPE_2 = #{cashType2}
and a.eff_date >= to_date(#{effDateStart},'yyyy-mm-dd')
and to_date(#{effDateEnd},'yyyy-mm-dd') >= a.eff_date
and (b.FINPROD_ID in
null) OR b.FINPROD_ID in (
#{item}
OR g.P_FINPROD_ID in
null) OR g.P_FINPROD_ID in (
#{item}
)
AND g.FINPROD_ID IN(
#{item}
)
order by a.Eff_Date desc

select a.CAWLBACK_RULE anapleroticRule,/*回补方式*/ a.CAWLBACK_TYPE anapleroticType, /*回补形式*/ a.Basis AnapleroticBasic, H.ast_vdate_type AstVluDateType,/*资产净值日*/ a.Eff_Date EffDate, a.cash_id AnapleroticId, b.FINPROD_ID FinprodId, h.remark Remark, g.FINPROD_ABBR FinprodAbbr, g.vdate, g.mdate, g.OPERATION_TYPE operationType, e.DEAL_MODE dealMode, g.CALENDAR_ID CalendarId, c.ACCR_CYCLE_UNIT AnapleroticFrequency, /*回补规则*/ c.ACCR_TDAY_RULE CycleTdayRule,/*营业日准则*/ c.F_ACCR_DATE FirstAnapleroticDate, c.F_ACCR_END_DATE FirstAnapleroticCycleEndDate,
f.COEFFICIENT*100 AnapleroticRatio, c.e_Accr_Date anapleroticEndDate, d.Accr_Str_Date firstAnapleroticCycleBegDate,
i.RATE_TYPE rateType, i.RATE*100 rate, i.INDEX_ID indexId, i.INDEX_SOURCE indexSource, i.COEFFICIENT coefficient, i.SPREAD_RATE*100 spreadRate, i.RESET_TYPE resetType
,j.PROD_STYLE prodStyle from FIN_CLAWBACK_CALC_RULE a inner join FIN_CASH_INFO b on b.cash_id= a.cash_id left join Fin_Float_Counting_Rule c on a.cash_id = c.cash_id and a.Eff_Date = c.EFF_DATE left join (select sc.CASH_ID,min(sc.Accr_Str_Date) Accr_Str_Date from FIN_FLOAT_ACCRUAL_SCHE sc group by sc.CASH_ID) d on a.cash_id = d.cash_id left join fin_product_add e on b.FINPROD_ID = e.FINPROD_ID left join Fin_Float_Calc_Rule_Detail f on a.cash_id = f.cash_id and a.Eff_Date = f.EFF_DATE left join fin_product g on b.FINPROD_ID = g.FINPROD_ID left join FIN_FLOAT_CALC_RULE h on a.cash_id = h.cash_id and a.Eff_Date = h.EFF_DATE left join FIN_BASE_RULE_INFO i on b.FINPROD_ID = i.FINPROD_ID and i.BASE_RULE_TYPE = #{baseRuleType03} and i.EFF_DATE = a.EFF_DATE left join PRD_LAYER_PARAM j on b.FINPROD_ID = j.FINPROD_ID where 1=1 and b.Finprod_Type = #{finprodType} and b.Is_Calc = #{isCalcY} and b.CASH_TYPE_1 = #{cashType1} and b.CASH_TYPE_2 = #{cashType2}
and a.eff_date= to_date(#{effdate},'yyyy-mm-dd')
and e.PORTFOLIO_ID = #{ptlId}
and ((b.FINPROD_ID = #{finprodId} and e.DEAL_MODE != #{dealMode11}) or (g.P_FINPROD_ID = #{finprodId} and e.DEAL_MODE = #{dealMode11}))
and a.cash_id = #{anapleroticId}

       select FIN_PRODUCT.FINPROD_ID id, FIN_PRODUCT.FINPROD_MARKET_ID || ':' || FIN_PRODUCT.FINPROD_ABBR text,
       			FIN_PRODUCT_ADD.DEAL_MODE object
	     from FIN_PRODUCT,FIN_PRODUCT_ADD,PTL_PORTFOLIO_AUTHORITY
	    where FIN_PRODUCT.FINPROD_TYPE = #{finprodType1}
	      and FIN_PRODUCT.FINPROD_TYPE2 = #{finprodType2}
	      and FIN_PRODUCT.P_FINPROD_ID IS NULL
	      and FIN_PRODUCT.PROFIT_TYPE != #{notProfitType}
		  and FIN_PRODUCT.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID
		  and FIN_PRODUCT_ADD.PORTFOLIO_ID = PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID	

		  and not exists (
		        select 1 from fin_product_add fpa where fin_product.FINPROD_ID =fpa.FINPROD_ID
		        and fin_product.profit_type = '01' and fpa.DEAL_MODE = '10'
		    )


         		and FIN_PRODUCT.FINPROD_ID = #{initValue}



			  	  and PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userId}





      and (FIN_PRODUCT.FINPROD_ID like concat(concat('%',#{search}),'%')
          or FIN_PRODUCT.FINPROD_MARKET_ID like concat(concat('%',#{search}),'%')
          or FIN_PRODUCT.FINPROD_ABBR like concat(concat('%',#{search}),'%'))

select a.CAWLBACK_RULE anapleroticRule,/*回补方式*/ a.CAWLBACK_TYPE anapleroticType, /*回补形式*/ a.Basis AnapleroticBasic, H.ast_vdate_type AstVluDateType,/*资产净值日*/ a.Eff_Date EffDate, a.cash_id AnapleroticId, b.FINPROD_ID FinprodId, h.remark Remark, g.FINPROD_ABBR FinprodAbbr, g.vdate, g.mdate, g.OPERATION_TYPE operationType, e.DEAL_MODE dealMode, g.CALENDAR_ID CalendarId, c.ACCR_CYCLE_UNIT AnapleroticFrequency, /*回补规则*/ c.ACCR_TDAY_RULE CycleTdayRule,/*营业日准则*/ c.F_ACCR_DATE FirstAnapleroticDate, c.F_ACCR_END_DATE FirstAnapleroticCycleEndDate, f.COEFFICIENT*100 AnapleroticRatio, c.e_Accr_Date anapleroticEndDate, d.Accr_Str_Date firstAnapleroticCycleBegDate,
i.RATE_TYPE rateType, i.RATE*100 rate, i.INDEX_ID indexId, i.INDEX_SOURCE indexSource, i.COEFFICIENT coefficient, i.SPREAD_RATE*100 spreadRate, i.RESET_TYPE resetType
,j.PROD_STYLE prodStyle from FIN_CLAWBACK_CALC_RULE a inner join FIN_CASH_INFO b on b.cash_id= a.cash_id left join Fin_Float_Counting_Rule c on a.cash_id = c.cash_id and a.Eff_Date = c.EFF_DATE left join (select sc.CASH_ID,min(sc.Accr_Str_Date) Accr_Str_Date from FIN_FLOAT_ACCRUAL_SCHE sc group by sc.CASH_ID) d on a.cash_id = d.cash_id left join fin_product_add e on b.FINPROD_ID = e.FINPROD_ID left join Fin_Float_Calc_Rule_Detail f on a.cash_id = f.cash_id and a.Eff_Date = f.EFF_DATE left join fin_product g on b.FINPROD_ID = g.FINPROD_ID left join FIN_FLOAT_CALC_RULE h on a.cash_id = h.cash_id and a.Eff_Date = h.EFF_DATE left join FIN_BASE_RULE_INFO i on b.FINPROD_ID = i.FINPROD_ID and i.BASE_RULE_TYPE = #{baseRuleType03} and i.EFF_DATE = a.EFF_DATE left join PRD_LAYER_PARAM j on b.FINPROD_ID = j.FINPROD_ID where 1=1 and b.Finprod_Type = #{finprodType} and b.Is_Calc = #{isCalcY} and b.CASH_TYPE_1 = #{cashType1} and b.CASH_TYPE_2 = #{cashType2}
and a.eff_date= to_date(#{effdate},'yyyy-mm-dd')
and e.PORTFOLIO_ID = #{ptlId}
and b.FINPROD_ID = #{finprodId}
and a.cash_id = #{anapleroticId}

select a.CAWLBACK_RULE anapleroticRule,/*回补方式*/ a.CAWLBACK_TYPE anapleroticType, /*回补形式*/ a.Basis AnapleroticBasic, H.ast_vdate_type AstVluDateType,/*资产净值日*/ a.Eff_Date EffDate, a.cash_id AnapleroticId, nvl(k.FINPROD_ID,b.FINPROD_ID) FinprodId, h.remark Remark, g.FINPROD_ABBR FinprodAbbr, g.vdate, g.mdate, g.OPERATION_TYPE operationType, e.DEAL_MODE dealMode, g.CALENDAR_ID CalendarId, c.ACCR_CYCLE_UNIT AnapleroticFrequency, /*回补规则*/ c.ACCR_TDAY_RULE CycleTdayRule,/*营业日准则*/ c.F_ACCR_DATE FirstAnapleroticDate, c.F_ACCR_END_DATE FirstAnapleroticCycleEndDate, f.COEFFICIENT*100 AnapleroticRatio, c.e_Accr_Date anapleroticEndDate, d.Accr_Str_Date firstAnapleroticCycleBegDate,
i.RATE_TYPE rateType, i.RATE*100 rate, i.INDEX_ID indexId, i.INDEX_SOURCE indexSource, i.COEFFICIENT coefficient, i.SPREAD_RATE*100 spreadRate, i.RESET_TYPE resetType
,case when k.FINPROD_ID is not null then b.FINPROD_ID else '' end as prodStyle from FIN_CLAWBACK_CALC_RULE a inner join FIN_CASH_INFO b on b.cash_id= a.cash_id left join Fin_Float_Counting_Rule c on a.cash_id = c.cash_id and a.Eff_Date = c.EFF_DATE left join (select sc.CASH_ID,min(sc.Accr_Str_Date) Accr_Str_Date from FIN_FLOAT_ACCRUAL_SCHE sc group by sc.CASH_ID) d on a.cash_id = d.cash_id left join fin_product_add e on b.FINPROD_ID = e.FINPROD_ID left join Fin_Float_Calc_Rule_Detail f on a.cash_id = f.cash_id and a.Eff_Date = f.EFF_DATE left join fin_product g on b.FINPROD_ID = g.FINPROD_ID left join FIN_FLOAT_CALC_RULE h on a.cash_id = h.cash_id and a.Eff_Date = h.EFF_DATE left join FIN_BASE_RULE_INFO i on b.FINPROD_ID = i.FINPROD_ID and i.BASE_RULE_TYPE = #{baseRuleType03} and i.EFF_DATE = a.EFF_DATE left join PRD_LAYER_PARAM j on b.FINPROD_ID = j.FINPROD_ID left join FIN_PRODUCT k on k.FINPROD_ID = g.P_FINPROD_ID where 1=1 and b.Finprod_Type = #{finprodType} and b.Is_Calc = #{isCalcY} and b.CASH_TYPE_1 = #{cashType1} and b.CASH_TYPE_2 = #{cashType2}
and a.eff_date= to_date(#{effDate},'yyyy-mm-dd')
and e.PORTFOLIO_ID = #{ptlId}
and ((b.FINPROD_ID = #{finprodId} and e.DEAL_MODE != #{dealMode11}) or (g.P_FINPROD_ID = #{finprodId} and e.DEAL_MODE = #{dealMode11}))
and a.cash_id = #{anapleroticId}

mapper.delete:
delete from FIN_BASE_RULE_INFO
where FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
and EFF_DATE = #{effDate,jdbcType=DATE}

        delete from FIN_BASE_RULE_INFO
        where FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
	    and BASE_RULE_TYPE = #{baseRuleType}
        and EFF_DATE = #{effDate,jdbcType=DATE}
